#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const char *input;
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    input = argv[1];
    size_t len = strlen(input);
    if (len > 1024) {
        len = 1024; // limit processing to first 1024 characters
    }
    char out[1025]; // buffer for trimmed string (max 1024 chars + null)
    size_t out_idx = 0;
    int seen_nonspace = 0;   // have we output any non‑whitespace character yet?
    int pending_space = 0;   // a whitespace sequence was seen after last output char

    // Skip leading whitespace
    size_t i = 0;
    while (i < len && isspace((unsigned char)input[i])) {
        ++i;
    }

    for (; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f') {
            // Remember that we have encountered whitespace; it will become a single space
            // only if another non‑whitespace character follows.
            pending_space = 1;
        } else {
            if (pending_space && seen_nonspace) {
                out[out_idx++] = ' ';
            }
            out[out_idx++] = c;
            seen_nonspace = 1;
            pending_space = 0;
        }
    }
    // No need to add a trailing space – pending_space is ignored at the end.
    out[out_idx] = '\0';

    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }
    return 0;
}
